mkdir -p bin src test && cat > package.json <<'EOF'
{
  "name": "color-cli",
  "version": "0.1.0",
  "description": "Node.js CLI that detects terminal color support before printing colored text",
  "type": "module",
  "bin": {
    "color-cli": "./bin/cli.js"
  },
  "engines": {
    "node": ">=18"
  },
  "scripts": {
    "start": "node bin/cli.js",
    "test": "node --test"
  },
  "license": "MIT"
}
EOF
cat > src/color.js <<'EOF'
/**
 * Detect how many colors a stream supports.
 * Returns 0 (none), 16, 256, or 16777216 (truecolor).
 *
 * Precedence (highest first):
 *   1. CLI flags: --no-color / --color[=0|1|2|3]
 *   2. FORCE_COLOR env var (https://force-color.org)
 *   3. NO_COLOR env var (https://no-color.org)
 *   4. Non-TTY stream or TERM=dumb -> no color
 *   5. Node's built-in stream.getColorDepth()
 */
const LEVELS = [0, 16, 256, 16777216];

export function colorDepth(stream = process.stdout, { env = process.env, argv = process.argv } = {}) {
  if (argv.includes('--no-color') || argv.includes('--color=false')) return 0;
  const flag = argv.find((a) => a === '--color' || a.startsWith('--color='));
  if (flag) return levelFrom(flag.split('=')[1] ?? '1');

  if ('FORCE_COLOR' in env) return levelFrom(env.FORCE_COLOR);
  if (env.NO_COLOR) return 0;

  if (!stream?.isTTY || env.TERM === 'dumb') return 0;
  return typeof stream.getColorDepth === 'function' ? 2 ** stream.getColorDepth(env) : 16;
}

function levelFrom(value) {
  if (value === '' || value === 'true') return 16;
  if (value === 'false') return 0;
  const n = Number.parseInt(value, 10);
  return Number.isNaN(n) ? 16 : LEVELS[Math.min(Math.max(n, 0), 3)];
}

export function supportsColor(stream, opts) {
  return colorDepth(stream, opts) > 0;
}

/** Build color helpers bound to a stream; they become no-ops when color is unsupported. */
export function createColors(stream = process.stdout, opts) {
  const enabled = supportsColor(stream, opts);
  const wrap = (open, close) => (text) => (enabled ? `\x1b[${open}m${text}\x1b[${close}m` : String(text));
  return {
    enabled,
    bold: wrap(1, 22),
    dim: wrap(2, 22),
    red: wrap(31, 39),
    green: wrap(32, 39),
    yellow: wrap(33, 39),
    blue: wrap(34, 39),
    cyan: wrap(36, 39),
  };
}
EOF
cat > bin/cli.js <<'EOF'
#!/usr/bin/env node
import { colorDepth, createColors } from '../src/color.js';

const out = createColors(process.stdout);
const err = createColors(process.stderr);

if (process.argv.includes('--help') || process.argv.includes('-h')) {
  console.log(`Usage: color-cli [--color[=0-3]] [--no-color]

Environment:
  NO_COLOR      Disable color when set to a non-empty value
  FORCE_COLOR   Force color level (0-3), overrides NO_COLOR and TTY detection`);
  process.exit(0);
}

console.log(out.bold('Color support check'));
console.log(`  stdout: ${colorDepth(process.stdout)} colors`);
console.log(`  stderr: ${colorDepth(process.stderr)} colors`);
console.log(out.green('✔ success'), out.yellow('⚠ warning'), out.cyan('ℹ info'));
console.error(err.red('✖ error output (stderr)'));
EOF
chmod +x bin/cli.js
cat > test/color.test.js <<'EOF'
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { colorDepth, createColors } from '../src/color.js';

const tty = { isTTY: true, getColorDepth: () => 8 };
const pipe = { isTTY: false };
const opts = (env = {}, argv = []) => ({ env, argv });

test('TTY uses Node detection', () => assert.equal(colorDepth(tty, opts()), 256));
test('non-TTY disables color', () => assert.equal(colorDepth(pipe, opts()), 0));
test('TERM=dumb disables color', () => assert.equal(colorDepth(tty, opts({ TERM: 'dumb' })), 0));
test('NO_COLOR disables color', () => assert.equal(colorDepth(tty, opts({ NO_COLOR: '1' })), 0));
test('empty NO_COLOR is ignored', () => assert.equal(colorDepth(tty, opts({ NO_COLOR: '' })), 256));
test('FORCE_COLOR enables on pipe', () => assert.equal(colorDepth(pipe, opts({ FORCE_COLOR: '3' })), 16777216));
test('FORCE_COLOR=0 disables', () => assert.equal(colorDepth(tty, opts({ FORCE_COLOR: '0' })), 0));
test('--no-color beats FORCE_COLOR', () =>
  assert.equal(colorDepth(tty, opts({ FORCE_COLOR: '1' }, ['--no-color'])), 0));
test('--color forces on pipe', () => assert.equal(colorDepth(pipe, opts({}, ['--color'])), 16));

test('helpers are plain text when disabled', () => {
  assert.equal(createColors(pipe, opts()).red('hi'), 'hi');
  assert.equal(createColors(tty, opts()).red('hi'), '\x1b[31mhi\x1b[39m');
});
EOF
cat > .gitignore <<'EOF'
node_modules/
EOF
npm test 2>&1 | tail -12; echo ---; node bin/cli.js | cat -v; echo ---; FORCE_COLOR=1 node bin/cli.js 2>&1 | cat -v

